const crypto = require('crypto');
const secret = $env.ADVISORAI_N8N_HMAC_SECRET;
const base = String($env.ADVISORAI_API_BASE_URL || '').replace(/\/$/, '');
if (!secret || !base) throw new Error('advisorai_env_missing');
const { path } = $json; const body = $json.body || '';
if (!String(path).startsWith('/internal/orchestrator/v1/')) throw new Error('path_not_allowed');
const tries = Math.max(1, Number($json.max_tries) || 1);
const backoff = Math.max(0, Number($json.backoff_ms) || 0);
const timeout = Math.max(1000, Number($json.timeout_ms) || 60000);
for (let attempt = 1; attempt <= tries; attempt++) {
  const ts = String(Math.floor(Date.now() / 1000));
  const hash = crypto.createHash('sha256').update(body).digest('hex');
  const sig = crypto.createHmac('sha256', secret).update(`${ts}.POST.${path}.${hash}`).digest('hex');
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', url: base + path, timeout,
      headers: { 'Content-Type': 'application/json', 'X-Advisorai-Timestamp': ts, 'X-Advisorai-Signature': sig },
      ...(body ? { body } : {}),
    });
    const parsed = typeof res === 'string' ? JSON.parse(res) : res;
    return [{ json: { ok: true, result: parsed } }];
  } catch (e) {
    const status = Number(e.httpCode || (e.response && e.response.status) || 0);
    if (status >= 400 && status < 500) return [{ json: { ok: false, code: `orchestrator_http_${status}`, retryable: false } }];
    if (attempt < tries && backoff) await new Promise((r) => setTimeout(r, backoff));
  }
}
return [{ json: { ok: false, code: 'orchestrator_http_error', retryable: true } }];
